// Works with the WhatsApp Trigger output (the 'value' object of the Cloud API webhook)
const out = [];
for (const item of $input.all()) {
  const v = item.json.entry ? item.json.entry[0].changes[0].value : item.json;
  for (const m of (v.messages || [])) {
    if (m.type !== 'text') continue; // images, voice notes etc. go to a human
    const contact = (v.contacts || []).find(c => c.wa_id === m.from) || {};
    out.push({ json: { phone: m.from, name: (contact.profile && contact.profile.name) || '', text: m.text.body, message_id: m.id,
      phone_number_id: v.metadata && v.metadata.phone_number_id, at: new Date(Number(m.timestamp) * 1000).toISOString() } });
  }
}
return out;

// Last 12 messages become the conversation Claude sees
const msg = $('Extract Message').first().json;
const rows = $input.all().map(r => r.json).filter(r => r.text).slice(-12);
const messages = rows.map(r => ({ role: r.direction === 'in' ? 'user' : 'assistant', content: String(r.text) }));
// Claude needs alternating turns that start with the user
const merged = [];
for (const m of messages) { if (merged.length && merged[merged.length - 1].role === m.role) merged[merged.length - 1].content += '\n' + m.content; else merged.push({ ...m }); }
while (merged.length && merged[0].role !== 'user') merged.shift();
if (!merged.length || merged[merged.length - 1].role !== 'user') merged.push({ role: 'user', content: msg.text });
return [{ json: { ...msg, history: merged } }];

const claudeJson = r => { const t = (r.content && r.content[0] && r.content[0].text) || ''; return JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); };
const msg = $('Build History').first().json;
let ai = { reply: 'Thanks for your message. An advisor will get back to you shortly.', handoff: true, lead: {}, summary: 'AI reply could not be parsed' };
try { ai = { ...ai, ...claudeJson($input.first().json) }; } catch (e) {}
return [{ json: { ...msg, ...ai, history: undefined } }];

